b=json.load(open('../blinded-fable/checks/checks_2steps.json'))
def flat(o,p='',acc=None):
    if acc is None: acc={}
    if isinstance(o,dict):
        for k,v in o.items(): flat(v,p+'/'+str(k),acc)
    elif isinstance(o,list):
        for i,v in enumerate(o): flat(v,p+'/'+str(i),acc)
